<?php
session_start();require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/includes/icons.php';
$token=trim($_POST['token']??$_GET['token']??'');$mensaje='';$valida=false;$invitacion=null;
if(empty($_SESSION['activation_csrf']))$_SESSION['activation_csrf']=bin2hex(random_bytes(32));
if(preg_match('/^[a-f0-9]{64}$/',$token)){
    try{$pdo=conectarBD();$hash=hash('sha256',$token);$stmt=$pdo->prepare("SELECT i.id,i.usuario_id,u.nombre,u.nombre_usuario,r.nombre rol FROM invitaciones_usuario i JOIN usuarios u ON u.id=i.usuario_id JOIN roles r ON r.id=u.rol_id WHERE i.token_hash=:hash AND i.usado_at IS NULL AND i.expira_at>now() AND u.activo=FALSE");$stmt->execute(['hash'=>$hash]);$invitacion=$stmt->fetch();$valida=(bool)$invitacion;}catch(Throwable $e){error_log($e->getMessage());$mensaje='No se pudo validar la invitación.';}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&$valida){
    $csrf=$_POST['csrf_token']??'';$clave=$_POST['contrasena']??'';$confirmacion=$_POST['confirmar']??'';
    if(!is_string($csrf)||!hash_equals($_SESSION['activation_csrf'],$csrf)){http_response_code(403);exit('Solicitud no válida.');}
    if(strlen($clave)<8||!preg_match('/[A-Za-z]/',$clave)||!preg_match('/\d/',$clave)||$clave!==$confirmacion){$mensaje='La contraseña debe tener al menos 8 caracteres, letras y números, y ambas deben coincidir.';}
    else{try{$pdo->beginTransaction();$lock=$pdo->prepare("SELECT id FROM invitaciones_usuario WHERE id=:id AND usado_at IS NULL AND expira_at>now() FOR UPDATE");$lock->execute(['id'=>$invitacion['id']]);if(!$lock->fetch())throw new RuntimeException('La invitación ya no está disponible.');$pdo->prepare('UPDATE usuarios SET contrasena_hash=:hash,activo=TRUE,updated_at=now() WHERE id=:id')->execute(['hash'=>password_hash($clave,PASSWORD_DEFAULT),'id'=>$invitacion['usuario_id']]);$pdo->prepare('UPDATE invitaciones_usuario SET usado_at=now() WHERE id=:id')->execute(['id'=>$invitacion['id']]);$pdo->commit();$_SESSION['activation_csrf']=bin2hex(random_bytes(32));$valida=false;$mensaje='Cuenta activada correctamente. Ya puedes iniciar sesión.';$activada=true;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log($e->getMessage());$mensaje='No se pudo activar la cuenta.';}}
}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Activar cuenta - Clínica Vida Salud</title><link rel="icon" href="assets/images/isotipo-vida-salud.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/css/modern.css?v=20261101-medico3"></head><body class="auth-simple"><main class="auth-simple-shell"><a class="btn btn-secondary" href="login_moderno.php"><?= icono('volver') ?> Volver al inicio de sesión</a><section class="card"><div class="card-header"><div class="section-title"><span class="page-emblem blue"><?= icono('hospital') ?></span><div><p class="doctor-eyebrow">Clínica Vida Salud</p><h1 class="card-title">Activa tu cuenta</h1></div></div></div><div class="card-body">
<?php if($mensaje): ?><div class="alert <?= !empty($activada)?'alert-success':'alert-error' ?>"><?= htmlspecialchars($mensaje) ?></div><?php endif; ?>
<?php if(!empty($activada)): ?><a class="btn btn-primary" href="login_moderno.php">Ir al inicio de sesión</a><?php elseif(!$valida): ?><p>El enlace es inválido, ya fue utilizado o ha caducado.</p><p class="form-hint">Solicita una nueva invitación a administración para habilitar tu acceso.</p><?php else: ?><p class="form-hint">Hola, <strong><?= htmlspecialchars($invitacion['nombre']) ?></strong>. Activa la cuenta <strong><?= htmlspecialchars($invitacion['nombre_usuario']) ?></strong> para ingresar como <?= htmlspecialchars($invitacion['rol']) ?>. Usa al menos 8 caracteres con letras y números.</p><form method="POST"><input type="hidden" name="token" value="<?= htmlspecialchars($token) ?>"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['activation_csrf']) ?>"><div class="form-group"><label class="form-label required" for="activar-clave">Nueva contraseña</label><input id="activar-clave" class="form-input" type="password" name="contrasena" minlength="8" required autocomplete="new-password"></div><div class="form-group"><label class="form-label required" for="activar-confirmacion">Confirmar contraseña</label><input id="activar-confirmacion" class="form-input" type="password" name="confirmar" minlength="8" required autocomplete="new-password"></div><button class="btn btn-primary" type="submit"><?= icono('escudo') ?> Activar mi cuenta</button></form><?php endif; ?>
</div></section></main></body></html>
